remaining = for page in list.range(2, first.total_pages + 1) {
    result = list_contacts({ page })
    return result.items
}
contacts = fold acc = first.items for page in remaining {
    return acc + page
}

# Build domain -> company name map
domain_map = fold acc = {} for c in companies {
    return acc + { [c.domain]: c.name }
}

# Digits-only helper via regex
normalize_phone = for c in contacts {
    phone = c.phone if c.phone != null else ""
    already_ok = regex.test(phone, "^\\+1\\d{10}$")
    digits_match = regex.captures(phone, "(\\d+)")
    # extract all digits
    all_digit_parts = regex.find_all(phone, "\\d+")
    digits = text.join(all_digit_parts, "")
    new_phone = if already_ok {
        return phone
    } else if text.starts_with(digits, "1") and text.length(digits) == 11 {
        return "+" + digits
    } else if text.length(digits) == 10 {
        return "+1" + digits
    } else if text.length(digits) == 11 and text.starts_with(digits, "1") {
        return "+" + digits
    } else {
        # try best effort: if more digits, take last 10 with +1?
        return phone
    }
    need_phone = (not already_ok) and (new_phone != phone) and regex.test(new_phone, "^\\+1\\d{10}$")

    email = c.email if c.email != null else ""
    # extract domain
    email_parts = text.split(email, "@")
    domain = email_parts[1] if list.length(email_parts) >= 2 else ""
    company_empty = c.company == null or c.company == ""
    matched_company = domain_map[domain] if domain in domain_map else null
    need_company = company_empty and matched_company != null

    skip if not need_phone and not need_company

    updated = update_contact({
        id: c.id,
        phone: new_phone if need_phone else null,
        company: matched_company if need_company else null
    })
    return {
        id: c.id,
        phone_fixed: need_phone,
        company_filled: need_company
    }
}

phones_fixed = fold acc = 0 for u in normalize_phone {
    return acc + (1 if u.phone_fixed else 0)
}
companies_filled = fold acc = 0 for u in normalize_phone {
    return acc + (1 if u.company_filled else 0)
}

return {
    phones_fixed: phones_fixed,
